use crate::aap::caps::notifier;
use crate::aap::caps::types::{Category, Importance};

struct Node;

fn cat(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn imp(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "must-read",
        Importance::WorthALook => "worth-a-look",
        Importance::Skip => "skip",
    }
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let mut msg = String::new();
        msg.push_str("Digest ");
        msg.push_str(&composed.date);
        msg.push('\n');
        msg.push_str(&composed.overview);
        msg.push('\n');
        for e in composed.entries.iter().filter(|e| e.kept) {
            msg.push_str("- [");
            msg.push_str(imp(e.importance));
            msg.push('/');
            msg.push_str(cat(e.category));
            msg.push_str("] ");
            msg.push_str(&e.title);
            msg.push_str(" (");
            msg.push_str(&e.link);
            msg.push_str(") ");
            msg.push_str(&e.summary);
            msg.push('\n');
        }
        let published = notifier::notify(&msg);
        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
